    with ThreadPoolExecutor(max_workers=target_concurrency) as executor:
        results = list(executor.map(_run_command, chunks))

    exit_codes, outputs = zip(*results)
    final_output = b''.join(outputs)
    if any(code != 0 for code in exit_codes):
        raise subprocess.CalledProcessError(returncode=max(exit_codes), cmd=cmd, output=final_output)
    return 0, final_output

