def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _legacy_mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    from collections import defaultdict

    graph = defaultdict(list)
    nodes = set()

    def add_link(n1, n2):
        graph[n1].append(n2)
        nodes.add(n1)
        nodes.add(n2)

    for ordering in orderings:
        last = None
        for item in ordering:
            if last is not None:
                add_link(last, item)
            last = item

    def find_scc():
        index = 0
        stack = []
        indices = {}
        lowlinks = {}
        on_stack = set()
        sccs = []

        def strongconnect(node):
            nonlocal index
            indices[node] = index
            lowlinks[node] = index
            index += 1
            stack.append(node)
            on_stack.add(node)

            for neighbor in graph[node]:
                if neighbor not in indices:
                    strongconnect(neighbor)
                    lowlinks[node] = min(lowlinks[node], lowlinks[neighbor])
                elif neighbor in on_stack:
                    lowlinks[node] = min(lowlinks[node], indices[neighbor])

            if lowlinks[node] == indices[node]:
                scc = []
                while True:
                    w = stack.pop()
                    on_stack.remove(w)
                    scc.append(w)
                    if w == node:
                        break
                sccs.append(scc)

        for node in nodes:
            if node not in indices:
                strongconnect(node)

        return sccs

    def topological_sort():
        visited = set()
        order = []

        def visit(node):
            if node in visited:
                return
            visited.add(node)
            for neighbor in graph[node]:
                visit(neighbor)
            order.append(node)

        for node in nodes:
            visit(node)

        return order

    sccs = find_scc()
    # This ensures that nodes within the same SCC are treated as a single node
    scc_map = {}
    new_nodes = []
    for i, scc in enumerate(sccs):
        for node in scc:
            scc_map[node] = i
        new_nodes.append(i)

    scc_graph = defaultdict(list)
    for n1, n2 in graph.items():
        scc1 = scc_map[n1]
        for n2 in n2:
            scc2 = scc_map[n2]
            if scc1 != scc2:
                scc_graph[scc1].append(scc2)

    order = topological_sort()
    result = []
    visited_scc = set()
    for scc_idx in order:
        if scc_idx not in visited_scc:
            visited_scc.add(scc_idx)
            scc = sccs[scc_idx]
            # Merge nodes within the same SCC maintaining their relative order
            scc_order = topological_sort()
            result.extend([node for node in scc_order if node in scc])

    return result

def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _legacy_mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    merged = []
    while orderings:
        for i, ordering in enumerate(orderings):
            suffix = [x for x in ordering if x not in merged]
            if not suffix:
                continue
            for j, other in enumerate(orderings):
                if i != j:
                    for k, item in enumerate(other):
                        if item == suffix[0]:
                            if other[k:] != suffix[:len(other) - k]:
                                raise ValueError("Order conflict detected")
            merged.extend(suffix)
            del orderings[i]
            break
    return merged

