def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re

    key_regex = r'^[a-zA-Z0-9_]+$'
    value_regex = r'^[a-zA-Z0-9_ ,\-]+$'

    errors = []

    for key, value in labels.items():
        try:
            # Check if key matches the regex
            if not re.match(key_regex, str(key)):
                errors.append({str(key): f"Label key '{key}' does not match the regex {key_regex}"})
            # Check if value is a list, if so validate each element in the list
            if isinstance(value, list):
                for item in value:
                    if not isinstance(item, str):
                        errors.append({str(item): 'expected string or bytes-like object'})
                    elif not re.match(value_regex, item):
                        errors.append({str(item): f"Label value '{item}' does not match the regex {value_regex}"})
            # If value is not a list, just validate it
            elif not isinstance(value, str):
                errors.append({str(value): 'expected string or bytes-like object'})
            elif not re.match(value_regex, value):
                errors.append({str(value): f"Label value '{value}' does not match the regex {value_regex}"})
        except Exception as e:
            errors.append({str(key): str(e)})

    if errors:
        raise ValidationError(errors)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    from collections.abc import Iterable

    key_regex = re.compile(r'^[a-zA-Z_][a-zA-Z0-9_]*$')
    value_regex = re.compile(r'^[a-zA-Z0-9_]+$')
    errors = []

    for key, value in labels.items():
        try:
            key_str = str(key)
            if not key_regex.match(key_str):
                errors.append({key_str: f"Label key '{key_str}' does not match the regex '^[a-zA-Z_][a-zA-Z0-9_]*$'"})
        except TypeError as e:
            errors.append({str(key): str(e)})

        if isinstance(value, Iterable) and not isinstance(value, str):
            try:
                value_str = ','.join(map(str, value))
                if not all(value_regex.match(str(item)) for item in value):
                    errors.append({value_str: f"Label value '{value_str}' does not match the regex '^[a-zA-Z0-9_]+$'"})
            except TypeError as e:
                errors.append({str(value): str(e)})
        else:
            try:
                value_str = str(value)
                if not value_regex.match(value_str):
                    errors.append({value_str: f"Label value '{value_str}' does not match the regex '^[a-zA-Z0-9_]+$'"})
            except TypeError as e:
                errors.append({str(value): str(e)})

    if errors:
        raise ValidationError(errors)

