def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    try:
        for manifest in manifest_files:
            for digest in manifest.get_required_digests():
                if digest not in manifest.get_all_digests():
                    raise ValueError(f"Digest {digest} is required but not present in the manifest.")
                if digest not in digests_used:
                    raise ValueError(f"Digest {digest} is present in the manifest but not used.")
    except Exception as e:
        raise RuntimeError(f"An error occurred while checking digests: {str(e)}")

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    try:
        required_digests = set(manifest_files.keys())
        provided_digests = set(digests_used.keys())

        missing_digests = required_digests - provided_digests
        unused_digests = provided_digests - required_digests

        if missing_digests:
            raise ValueError(f"Missing digests in manifest: {missing_digests}")
        if unused_digests:
            raise ValueError(f"Unused digests provided: {unused_digests}")

        for digest, files in manifest_files.items():
            if not digests_used.get(digest):
                raise ValueError(f"Digest {digest} is present but not used for any file in {files}")
    except (AttributeError, TypeError) as e:
        raise ValueError(f"Invalid input: {e}")
    except Exception as e:
        raise RuntimeError(f"An unexpected error occurred: {e}")

