def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError("The prior object must be an instance of InventoryValidator")

    # Check that all items in the prior version are present in the current version
    for item_id, item_data in prior.inventory.items():
        if item_id not in self.inventory:
            raise ValueError(f"Item {item_id} is missing in the current inventory that is present in the prior inventory.")

    # Check that all items in the current version that were in the prior version have not been altered
    for item_id, prior_item_data in prior.inventory.items():
        if item_id in self.inventory:
            current_item_data = self.inventory[item_id]
            if prior_item_data != current_item_data:
                raise ValueError(f"Item {item_id} has been altered in the current inventory compared to the prior inventory.")

