def _group_files_by_xml_filename(source, xmls, files):
    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    xml_filename : str
        XML filenames
    files : list
        list of files in the folder or zipfile

    Returns
    -------
    dict
        key: name of the XML files
        value: Package
    """
    from os.path import basename

    grouped_files = {}
    try:
        xml_bases = {basename(xml): xml for xml in xmls}
        for file in files:
            file_base = basename(file)
            for xml_base in xml_bases:
                if file_base.startswith(xml_base) or file_base.endswith(xml_base):
                    if xml_bases[xml_base] not in grouped_files:
                        grouped_files[xml_bases[xml_base]] = []
                    grouped_files[xml_bases[xml_base]].append(file)
    except Exception as e:
        print(f"An error occurred: {e}")

    return grouped_files

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os

    if not isinstance(folder, str):
        raise TypeError("The folder parameter must be a string.")

    if not os.path.isdir(folder):
        raise ValueError("The folder parameter must be a valid directory path.")

    data = {}

    try:
        for filename in os.listdir(folder):
            if filename.endswith('.xml'):
                base_name = os.path.basename(filename).rsplit('.', 1)[0]
                if base_name not in data:
                    data[base_name] = []
                data[base_name].append(os.path.join(folder, filename))
    except Exception as e:
        raise RuntimeError(f"An error occurred while exploring the folder: {e}")

    return data

