    pretty_repr = f"{indent_str}<{self.__class__.__name__}>\n"
    for attr, value in self.__dict__.items():
        if not attr.startswith('_'):
            if hasattr(value, 'pretty'):
                pretty_repr += f"{value.pretty(indent + 1, debug)}\n"
