def normalized(self):
    """
    Return a version of this object represented entirely using integer
    values for the relative attributes.

    >>> relativedelta(days=1.5, hours=2).normalized()
    relativedelta(days=+1, hours=+14)

    :return:
        Returns a :class:`dateutil.relativedelta.relativedelta` object.
    """
    from dateutil.relativedelta import relativedelta

    # Initialize the parameters dictionary with zero for all possible relativedelta attributes
    params = {
        'years': 0,
        'months': 0,
        'days': 0,
        'leapdays': 0,
        'weeks': 0,
        'hours': 0,
        'minutes': 0,
        'seconds': 0,
        'microseconds': 0
    }

    # Copy the current attributes to the parameters
    for attr in params.keys():
        if hasattr(self, attr):
            params[attr] = getattr(self, attr)

    # Normalize the attributes
    # Convert larger units to smaller units if necessary
    if params['weeks'] != 0:
        params['days'] += params['weeks'] * 7
        params['weeks'] = 0

    if params['days'] != 0:
        params['hours'] += params['days'] * 24
        params['days'] = 0

    if params['hours'] != 0:
        params['minutes'] += params['hours'] * 60
        params['hours'] = 0

    if params['minutes'] != 0:
        params['seconds'] += params['minutes'] * 60
        params['minutes'] = 0

    if params['seconds'] != 0:
        params['microseconds'] += params['seconds'] * 1_000_000
        params['seconds'] = 0

    # Handle fractional parts for each attribute by augmenting the next smaller attribute
    for attr in ['years', 'months']:
        if not isinstance(params[attr], int):
            fractional, integer = math.modf(params[attr])
            params[attr] = integer
            if attr == 'years':
                params['months'] += fractional * 12
            elif attr == 'months':
                # Assume an average month length of 30 days for simplicity
                params['days'] += fractional * 30

    for attr in ['weeks', 'days', 'hours', 'minutes', 'seconds']:
        if not isinstance(params[attr], int):
            fractional, integer = math.modf(params[attr])
            params[attr] = integer
            if attr == 'days':
                params['hours'] += fractional * 24
            elif attr == 'hours':
                params['minutes'] += fractional * 60
            elif attr == 'minutes':
                params['seconds'] += fractional * 60
            elif attr == 'seconds':
                params['microseconds'] += fractional * 1_000_000

    if not isinstance(params['microseconds'], int):
        fractional, integer = math.modf(params['microseconds'])
        params['microseconds'] = integer

    # Return a new relativedelta object with the normalized attributes
    return relativedelta(**params)

