def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    if not commands:
        raise ValueError("No commands provided to run.")

    if not isinstance(commands, list):
        commands = [commands]

    if cwd and not os.path.isdir(cwd):
        raise ValueError(f"The specified working directory {cwd} does not exist.")

    full_command = [str(cmd) for cmd in commands] + [str(arg) for arg in args]

    try:
        if verbose:
            print("Running command:", ' '.join(full_command))

        subprocess_env = os.environ.copy()
        if env:
            subprocess_env.update(env)

        with subprocess.Popen(full_command, cwd=cwd, env=subprocess_env, 
                              stderr=subprocess.PIPE if hide_stderr else subprocess.STDOUT, 
                              stdout=subprocess.PIPE, text=True) as process:
            output, _ = process.communicate()

            if process.returncode != 0:
                raise subprocess.CalledProcessError(process.returncode, full_command, output=output)

    except Exception as e:
        raise RuntimeError(f"An error occurred while running the command: {e}") from e

    return output

