            continue
        except Exception as e:
            raise Exception(f"Error reading inventory for version {version}: {e}")

        for key, digest in version_inventory.items():
            if key not in root_inventory or root_inventory[key] != digest:
                if version not in divergent_inventories:
                    divergent_inventories[version] = {}
                divergent_inventories[version][key] = digest

    return divergent_inventories

