    merged_dict = {}

    for key_node, value_node in nodes:
        key = key_node.value

        if key in merged_dict:
            if isinstance(value_node, MappingNode) and isinstance(merged_dict[key][1], MappingNode):
                # Recursively merge MappingNodes
                merged_dict[key][1].value.extend(value_node.value)
                # Ensure uniqueness of keys in the merged MappingNode
                unique_values = {}
                for k, v in merged_dict[key][1].value:
                    unique_values[k.value] = (k, v)
                merged_dict[key][1].value = list(unique_values.values())
            else:
                # Last value wins for non-MappingNode values
                merged_dict[key] = (key_node, value_node)
        else:
            merged_dict[key] = (key_node, value_node)

    # Convert merged_dict back to a list of tuples
    return list(merged_dict.values())

def deep_merge_nodes(nodes):
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    merged_dict = {}

    for key_node, value_node in nodes:
        key = key_node.value
        if key not in merged_dict:
            merged_dict[key] = (key_node, value_node)
        else:
            _, existing_value_node = merged_dict[key]
            if isinstance(value_node, MappingNode) and isinstance(existing_value_node, MappingNode):
                existing_value_dict = dict(existing_value_node.value)
                new_value_dict = dict(value_node.value)
                existing_value_dict.update(new_value_dict)
                existing_value_node.value = list(existing_value_dict.items())
            else:
                merged_dict[key] = (key_node, value_node)

    return list(merged_dict.values())

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    def merge_mappings(mapping1, mapping2):
        merged_value = {}
        for key, value in mapping1.value:
            merged_value[key.value] = (key, value)
        for key, value in mapping2.value:
            if key.value in merged_value and isinstance(value, MappingNode) and isinstance(merged_value[key.value][1], MappingNode):
                merged_value[key.value] = (key, merge_mappings(merged_value[key.value][1], value))
            else:
                merged_value[key.value] = (key, value)
        return MappingNode(mapping1.tag, list(merged_value.values()), start_mark=mapping1.start_mark, end_mark=mapping1.end_mark)

    merged_nodes = {}
    for key, value in nodes:
        if key.value in merged_nodes and isinstance(value, MappingNode) and isinstance(merged_nodes[key.value][1], MappingNode):
            merged_nodes[key.value] = (key, merge_mappings(merged_nodes[key.value][1], value))
        else:
            merged_nodes[key.value] = (key, value)

    return list(merged_nodes.values())

