    '''
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    def merge_values(value1, value2):
        if isinstance(value1, MappingNode) and isinstance(value2, MappingNode):
            merged_value = {k: v for k, v in value1.value}
            for k, v in value2.value:
                merged_value[k] = merge_values(merged_value.get(k), v)
            return MappingNode(value1.tag, list(merged_value.items()), value1.start_mark, value1.end_mark)
        else:
            return value2

    merged_dict = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged_dict:
            merged_dict[key] = merge_values(merged_dict[key], value_node)
        else:
