def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    import argparse

    parser = argparse.ArgumentParser(description='Process some command-line arguments.')
    subparsers = parser.add_subparsers(dest='subparser_name')

    # Example of adding a subparser
    subparser1 = subparsers.add_parser('subcommand1', help='Subcommand 1 help')
    subparser1.add_argument('--foo', help='foo help')

    # Example of adding another subparser
    subparser2 = subparsers.add_parser('subcommand2', help='Subcommand 2 help')
    subparser2.add_argument('--bar', help='bar help')

    try:
        args = parser.parse_args(unparsed_arguments)
        return {args.subparser_name or "global": args}
    except argparse.ArgumentError as e:
        print(f"Argument parsing error: {e}")
        return {}
    except SystemExit:
        # This happens when the parser encounters an issue and tries to exit
        return {}

