            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    from collections import defaultdict

    merged = defaultdict(lambda: None)

    for key_node, value_node in nodes:
        key = key_node.value

        if isinstance(value_node, ruamel.yaml.nodes.MappingNode):
            if merged[key] is None:
                merged[key] = (key_node, value_node)
            else:
                _, existing_value_node = merged[key]
                existing_map = dict(existing_value_node.value)
                new_map = dict(value_node.value)

                for new_key, new_value in new_map.items():
                    if new_key in existing_map and isinstance(new_value, ruamel.yaml.nodes.MappingNode) and isinstance(existing_map[new_key], ruamel.yaml.nodes.MappingNode):
                        # Recursively merge mapping nodes
                        existing_map[new_key] = (new_key, deep_merge_nodes([existing_map[new_key], (new_key, new_value)])[0][1])
                    else:
                        existing_map[new_key] = new_value

                existing_value_node.value = list(existing_map.items())
        else:
            # Non-mapping nodes, last one wins
            merged[key] = (key_node, value_node)

    return list(merged.values())

def deep_merge_nodes(nodes):
    from ruamel.yaml.nodes import ScalarNode, MappingNode

    merged = {}

    for key_node, value_node in nodes:
        key = key_node.value

        if key not in merged:
            merged[key] = (key_node, value_node)
        else:
            existing_key_node, existing_value_node = merged[key]

            if isinstance(existing_value_node, MappingNode) and isinstance(value_node, MappingNode):
                existing_value_node.value.extend(value_node.value)
                # Remove duplicates by converting to a dictionary and back to a list of tuples
                existing_value_dict = {item[0].value: item for item in existing_value_node.value}
                existing_value_node.value = list(existing_value_dict.values())
            else:
                merged[key] = (key_node, value_node)

    return list(merged.values())

def deep_merge_nodes(nodes):
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    merged_dict = {}

    for key_node, value_node in nodes:
        key = key_node.value

        if key not in merged_dict:
            merged_dict[key] = (key_node, value_node)
        else:
            _, existing_value_node = merged_dict[key]

            if isinstance(value_node, MappingNode) and isinstance(existing_value_node, MappingNode):
                existing_value_node.value.extend(value_node.value)
            else:
                merged_dict[key] = (key_node, value_node)

    # Deduplicate items in MappingNode values
    for key, (_, value_node) in merged_dict.items():
        if isinstance(value_node, MappingNode):
            seen_keys = set()
            deduplicated_items = []
            for item_key_node, item_value_node in value_node.value:
                item_key = item_key_node.value
                if item_key not in seen_keys:
                    seen_keys.add(item_key)
                    deduplicated_items.append((item_key_node, item_value_node))
            value_node.value = deduplicated_items

    return list(merged_dict.values())

