def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    import argparse
    import borgmatic.commands
    import borgmatic.commands.arguments

    def get_subcommands(parser):
        try:
            return {action.dest: action.choices for action in parser._actions if isinstance(action, argparse._SubParsersAction)}
        except AttributeError:
            return {}

    def generate_completion_script(parser, name, parent_commands=''):
        script = []
        subcommands = get_subcommands(parser)
        script.append(f"_borgmatic_{name}() {{")
        script.append(f"    local cur prev opts")
        script.append(f"    COMPREPLY=()")
        script.append(f"    cur=${{COMP_WORDS[COMP_CWORD]}}")
        script.append(f"    prev=${{COMP_WORDS[COMP_CWORD-1]}}")
        script.append(f"    opts=\"{' '.join(parser._option_string_actions.keys())}\"")

        if subcommands:
            script.append(f"    case {{prev}} in")
            for subcommand, subparser in subcommands.items():
                script.append(f"        {subcommand})")
                script.append(generate_completion_script(subparser, subcommand, f"{parent_commands} {name}"))
                script.append(f"            ;;")
            script.append(f"    esac")

        script.append(f"    COMPREPLY=($(compgen -W \"{{opts}}\" -- {{cur}}))")
        script.append(f"}}")
        script.append(f"complete -F _borgmatic_{name} {parent_commands} {name}")

        return '\n'.join(script)

    main_parser = borgmatic.commands.arguments.parse_arguments(standalone_help=False)
    return generate_completion_script(main_parser, 'borgmatic')

