        import borgmatic.commands.arguments
    except ImportError:
        return "# borgmatic bash completion script could not be generated due to missing dependencies."

    def extract_arguments(parser):
        for action in parser._actions:
            if action.option_strings:
                yield from action.option_strings

    def generate_completion_script():
        parser = borgmatic.commands.arguments.parser()
        script = ["_borgmatic() {", "    local cur prev opts", "    COMPREPLY=()", "    cur=\"${COMP_WORDS[COMP_CWORD]}\""]
        script.append('    prev="${COMP_WORDS[COMP_CWORD-1]}"')
        script.append('    opts="' + ' '.join(sorted(extract_arguments(parser))) + '"')
