def parse_arguments(*unparsed_arguments):
    import argparse

    parser = argparse.ArgumentParser()
    subparsers = parser.add_subparsers(dest='subparser_name')

    # Example subparser
    parser_a = subparsers.add_parser('a')
    parser_a.add_argument('--foo', type=int, help='foo help')

    # Another subparser
    parser_b = subparsers.add_parser('b')
    parser_b.add_argument('--bar', type=str, help='bar help')

    # Global arguments
    parser.add_argument('--global_arg', type=str, help='global help')

    args = parser.parse_args(unparsed_arguments)

    # Parse all subparsers
    parsed_results = {'global': argparse.Namespace()}
    if args.global_arg:
        parsed_results['global'].global_arg = args.global_arg

    if args.subparser_name:
        parsed_results[args.subparser_name] = argparse.Namespace()
        if args.subparser_name == 'a':
            if args.foo:
                parsed_results['a'].foo = args.foo
        elif args.subparser_name == 'b':
            if args.bar:
                parsed_results['b'].bar = args.bar

    return parsed_results

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed_arguments = {}
    remaining_arguments = unparsed_arguments[:]

    for subparser_name, parser in subparsers.items():
        try:
            namespace, remaining = parser.parse_known_args(remaining_arguments)
            parsed_arguments[subparser_name] = namespace
            remaining_arguments = remaining
        except Exception as e:
            # Handle any exceptions that may occur during parsing
            print(f"Failed to parse arguments for subparser {subparser_name}: {e}")

    return parsed_arguments, remaining_arguments

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed_arguments = {}
    remaining_arguments = list(unparsed_arguments)

    for name, parser in subparsers.items():
        try:
            namespace, extras = parser.parse_known_args(remaining_arguments)
            parsed_arguments[name] = namespace
            remaining_arguments = extras
        except Exception as e:
            continue

    return parsed_arguments, remaining_arguments

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.upper()
    try:
        if size.endswith('K'):
            return int(size[:-1]) * 1000
        elif size.endswith('M'):
            return int(size[:-1]) * 1000**2
        elif size.endswith('G'):
            return int(size[:-1]) * 1000**3
        elif size.endswith('T'):
            return int(size[:-1]) * 1000**4
        else:
            return int(size)
    except ValueError:
        raise ValueError("Invalid size format. Expected format like '500K', '1M', etc.")

