def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    import sys

    if platform == 'this':
        platform = 1 if sys.platform.startswith('win') else 0

    if platform == 1:  # POSIX
        pattern = r"""(?u)(?:[^\s'"]*['"][^'"]*['"]*[^\s'"]*)+|[^\s]+"""
    elif platform == 0:  # Windows/CMD
        pattern = r"""(?u)"(?:\\.|[^"])*"|'(?:\\.|[^'])*'|[^\\s]+"""
    else:
        raise ValueError("Unsupported platform value")

    return re.findall(pattern, s)

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    import os

    if platform == 'this':
        platform = 1 if os.name == 'posix' else 0

    if platform == 1:  # POSIX
        pattern = r"(?:[^\s']+|'[^']*')\s*"
    elif platform == 0:  # Windows/CMD
        pattern = r'(?:[^\s"]+"[^"]*"|[^"]+\s*)'
    else:
        raise ValueError("Unsupported platform value")

    try:
        tokens = re.findall(pattern, s)
        return [token.strip().strip("'").strip('"') for token in tokens]
    except Exception as e:
        raise ValueError(f"Error splitting string: {e}")

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import subprocess
    from pathlib import Path

    try:
        tmp_path = Path(tmp_path)
        tmp_path.mkdir(parents=True, exist_ok=True)

        if filename is None:
            filename = Path(archive_path).stem

        repo_path = tmp_path / filename
        repo_path.mkdir(parents=True, exist_ok=True)

        # Uncompress the archive
        if archive_path.endswith('.zip'):
            subprocess.run(['unzip', archive_path, '-d', str(repo_path)], check=True)
        elif archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
            subprocess.run(['tar', '-xzf', archive_path, '-C', str(repo_path)], check=True)
        elif archive_path.endswith('.tar.bz2'):
            subprocess.run(['tar', '-xjf', archive_path, '-C', str(repo_path)], check=True)
        else:
            raise ValueError("Unsupported archive format")

        return f"file://{repo_path.resolve()}"

    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Error unpacking archive: {e}")
    except Exception as e:
        raise RuntimeError(f"An error occurred: {e}")

