def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        result = subprocess.run(['git', 'check-ignore', '-z', '-v', ignored], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, check=True)
        ignored_files = set()
        for line in result.stdout.split('\0'):
            parts = line.split()
            if len(parts) > 1:
                ignored_files.add(parts[-1])
        return ','.join(sorted(ignored_files))
    except subprocess.CalledProcessError as e:
        raise ValueError(f"Error running git command: {e.stderr}")

