            print(f"Error:\n{e.stderr}")
        raise subprocess.CalledProcessError(e.returncode, e.cmd, output=e.stdout, stderr=e.stderr) from e
    except Exception as e:
        if verbose:
            print(f"Command: {' '.join(full_command)}")
