def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    try:
        if isinstance(commands, str):
            commands = [commands]
        if verbose:
            print(f"Running: {' '.join(commands + args)} in {cwd}")
        with subprocess.Popen(
            commands + args,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE if hide_stderr else None,
            text=True
        ) as process:
            stdout, stderr = process.communicate()
            if process.returncode != 0:
                if stderr:
                    raise subprocess.CalledProcessError(process.returncode, commands + args, output=stdout, stderr=stderr)
                else:
                    raise subprocess.CalledProcessError(process.returncode, commands + args, output=stdout)
            if verbose:
                print(f"Output: {stdout}")
                if stderr:
                    print(f"Error: {stderr}")
            return stdout
    except Exception as e:
        if verbose:
            print(f"An error occurred: {e}")
        raise

