def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        mu = 0.2
        sigma = 0.1
        return (1 / (sigma * np.sqrt(2 * np.pi))) * np.exp(-0.5 * ((x - mu) / sigma) ** 2)
    except Exception as e:
        raise ValueError(f"An error occurred during the calculation: {str(e)}")

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import configparser
    import os

    configurations = {}
    errors = []

    for filename in config_filenames:
        config = configparser.ConfigParser()
        try:
            with open(filename) as f:
                config.read_file(f)
            if resolve_env:
                config = {section: {key: os.path.expandvars(value) for key, value in config.items(section)} for section in config.sections()}
            if overrides and filename in overrides:
                config.read_dict({section: overrides[filename] for section in overrides[filename]})
            configurations[filename] = config
        except Exception as e:
            record = logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=str(e), args=(), exc_info=True)
            errors.append(record)

    return configurations, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import configparser
    import os

    configs = {}
    log_records = []

    if overrides is None:
        overrides = {}

    for filename in config_filenames:
        config = configparser.ConfigParser()
        try:
            with open(filename, 'r') as file:
                config.read_file(file)
                if resolve_env:
                    for section in config.sections():
                        for key, value in config.items(section):
                            config.set(section, key, os.path.expandvars(value))

            # Apply overrides
            for section, options in overrides.items():
                if section in config:
                    for key, value in options.items():
                        config.set(section, key, value)

            configs[filename] = {section: dict(config.items(section)) for section in config.sections()}

        except Exception as e:
            log_record = logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0,
                                           msg=str(e), args=(), exc_info=True)
            log_records.append(log_record)

    return configs, log_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import configparser
    import os

    config_dict = {}
    log_records = []

    if overrides is None:
        overrides = {}

    for filename in config_filenames:
        config = configparser.ConfigParser()
        try:
            with open(filename, 'r') as f:
                config.read_file(f)
                if resolve_env:
                    for section in config.sections():
                        for key, value in config.items(section):
                            resolved_value = os.path.expandvars(value)
                            if resolved_value != value:
                                config.set(section, key, resolved_value)

                if filename in overrides:
                    for section, section_overrides in overrides[filename].items():
                        if not config.has_section(section):
                            config.add_section(section)
                        for key, value in section_overrides.items():
                            config.set(section, key, value)

                config_dict[filename] = {section: dict(config.items(section)) for section in config.sections()}
        except Exception as e:
            record = logging.makeLogRecord({
                'name': 'config_loader',
                'level': logging.ERROR,
                'pathname': filename,
                'msg': f"Failed to load configuration: {str(e)}"
            })
            log_records.append(record)

    return config_dict, log_records

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("Protocol version must be a tuple")

    handlers = {
        (3, 5): BoltProtocol35Handler,
        (4, 0): BoltProtocol40Handler,
        (4, 1): BoltProtocol41Handler
    }

    if protocol_version is not None:
        return {protocol_version: handlers.get(protocol_version)} if protocol_version in handlers else {}
    else:
        return handlers

