def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    if other is None:
        return self._scale

    if self._scale is None or self._scale == 0:
        raise ValueError("Graph has unknown or zero scale, cannot rescale.")

    try:
        factor = float(other) / self._scale
    except (TypeError, ValueError):
        raise TypeError("Scale factor must be a numeric value.")

    if len(self.data) == 0:
        return

    last_coord_index = len(self.data[0]) - 1
    for i in range(len(self.data)):
        self.data[i][last_coord_index] *= factor

    if self.errors:
        for i in range(len(self.errors)):
            self.errors[i][last_coord_index] *= factor

    self._scale = other

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    if other is None:
        if self._scale is None:
            raise AttributeError("Scale is not set for this graph.")
        return self._scale
    else:
        if not isinstance(other, (int, float)):
            raise TypeError("Scale must be a numeric value.")
        if other == 0:
            raise ValueError("Scale cannot be zero.")
        if self._scale is None:
            raise AttributeError("Cannot rescale graph with unknown scale.")
        try:
            scaling_factor = other / self._scale
            self._data = [(x, y * scaling_factor, error * scaling_factor) for x, y, error in self._data]
            self._scale = other
        except Exception as e:
            raise Exception(f"Error during rescaling: {e}")

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    errors = []

    if not tentative and not iface.providedBy(candidate):
        errors.append(f"Candidate does not provide the interface {iface}.")

    for name in iface.names(all=True):
        if name not in candidate.__dict__:
            if name not in candidate.__class__.__dict__:
                errors.append(f"Candidate does not define {name}.")

    for name, attribute in iface.getAttributes(all=True).items():
        if not hasattr(candidate, name):
            errors.append(f"Candidate does not define attribute {name}.")

    for name, method in iface.getMethods(all=True).items():
        if not hasattr(candidate, name):
            errors.append(f"Candidate does not define method {name}.")
        else:
            candidate_method = getattr(candidate, name)
            if not callable(candidate_method):
                errors.append(f"Candidate's {name} is not callable.")
            else:
                # This is a simple check and might not cover all cases
                from inspect import signature
                try:
                    sig = signature(candidate_method)
                    if len(sig.parameters) != len(signature(method).parameters):
                        errors.append(f"Candidate's method {name} has an incorrect number of parameters.")
                except ValueError as e:
                    errors.append(f"Could not check signature for method {name}: {e}")

    if errors:
        from zope.interface.exceptions import Invalid
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import zope.interface

    errors = []

    if not tentative:
        try:
            if not iface.providedBy(candidate):
                raise zope.interface.Invalid(f"Candidate does not provide the interface {iface}")
        except zope.interface.Invalid as e:
            errors.append(e)

    for name in iface.names():
        if name in iface.getTaggedValueTaggedValues('method'):
            if not hasattr(candidate, name) or not callable(getattr(candidate, name)):
                errors.append(zope.interface.Invalid(f"Candidate does not have a callable method {name}"))
            else:
                try:
                    method_spec = iface.get(name)
                    candidate_spec = zope.interface.signature(getattr(candidate, name))
                    if not candidate_spec.isSubsetOf(method_spec):
                        raise zope.interface.Invalid(f"Method {name} does not match the required signature")
                except zope.interface.Invalid as e:
                    errors.append(e)
        elif name in iface.getTaggedValueTaggedValues('attribute'):
            if not hasattr(candidate, name):
                errors.append(zope.interface.Invalid(f"Candidate does not have the required attribute {name}"))

    if errors:
        if len(errors) == 1:
            raise errors[0]
        else:
            raise zope.interface.Invalid("\n".join(str(e) for e in errors))

    return True

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    from zope.interface.verify import verifyObject as zope_verifyObject
    from zope.interface.exceptions import Invalid

    errors = []

    if not tentative:
        try:
            zope_verifyObject(iface, candidate, tentative=False)
        except Invalid as e:
            errors.append(str(e))

    for method_name in iface.names(all=True):
        method = iface.get(method_name)
        if callable(method):
            if not hasattr(candidate, method_name):
                errors.append(f"Missing method: {method_name}")
            else:
                candidate_method = getattr(candidate, method_name)
                if not callable(candidate_method):
                    errors.append(f"Attribute is not callable: {method_name}")
                else:
                    try:
                        method.__signature__.bind_partial(*candidate_method.__getattribute__('_getfullargspec').args)
                    except TypeError as e:
                        errors.append(f"Incorrect signature for method {method_name}: {e}")

    for attr_name in iface.names(all=True):
        attribute = iface.get(attr_name)
        if not callable(attribute):
            if not hasattr(candidate, attr_name):
                errors.append(f"Missing attribute: {attr_name}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid('\n'.join(errors))

    return True

