        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"{candidate} does not claim to provide {iface}.")

    for name in iface.names():
        if name not in getattr(candidate, '__dict__', {}):
            if not hasattr(candidate, name):
                errors.append(f"Missing attribute or method: {name}")

    for name, attribute in iface.getComponents(zope.interface.interfaces.IAttribute):
        if not hasattr(candidate, name):
            errors.append(f"Missing attribute: {name}")

    for name, method in iface.getComponents(zope.interface.interfaces.IMethod):
        if not hasattr(candidate, name):
            errors.append(f"Missing method: {name}")
        else:
            method_callable = getattr(candidate, name)
            if not callable(method_callable):
                errors.append(f"Attribute {name} is not callable.")
            else:
                method_signature = inspect.signature(method_callable)
                required_params = method.get('signature').parameters
                method_params = method_signature.parameters
                if len(required_params) != len(method_params):
                    errors.append(f"Method {name} has incorrect number of parameters.")
                for param_name in required_params:
                    if param_name not in method_params:
                        errors.append(f"Method {name} is missing parameter: {param_name}")

    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid("\n".join(errors))

    return True

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import zope.interface
    from zope.interface.exceptions import Invalid

    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"Candidate does not claim to provide the interface {iface}")

    for name in iface.names(all=True):
        if name not in candidate.__dict__ and not hasattr(candidate, name):
            errors.append(f"Missing {name}")
            continue

        attr = getattr(candidate, name)
        if zope.interface.interface.Attribute.providedBy(iface[name]):
            if not isinstance(attr, iface[name].__class__):
                errors.append(f"Attribute {name} has incorrect type")
        elif zope.interface.interface.Method.providedBy(iface[name]):
            if not callable(attr):
                errors.append(f"Method {name} is not callable")
            else:
                required_signature = iface[name].getSignatureString()
                if not hasattr(attr, '__call__'):
                    errors.append(f"Method {name} is not callable")
                else:
                    from inspect import signature
                    try:
                        candidate_signature = str(signature(attr))
                        if candidate_signature != required_signature:
                            errors.append(f"Method {name} has incorrect signature: {candidate_signature}, expected {required_signature}")
                    except ValueError:
                        errors.append(f"Could not determine signature for method {name}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

