def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    metas = sorted(set(type(b) for b in bases), key=lambda m: (m.__module__, m.__name__))
    if not metas:
        return type
    elif len(metas) == 1:
        return metas[0]
    else:
        return type('tmp', tuple(metas), {})

