    :return: list, list of argument names with matched ``required_when``
        condition
    """
    matched_args = []
    for option in options_spec:
        required_when = option.get('required_when')
        if required_when:
            try:
                condition_met = eval(required_when, {}, args)
            except Exception as e:
                raise ValueError(f"Error evaluating required_when condition for {option.get('name')}: {e}")
