def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess

    if not playbook_path:
        raise ValueError("playbook_path must be provided")

    command = ['ansible-playbook', playbook_path]

    if verbose:
        command.extend(['-v'] * verbose)

    if extra_vars:
        command.extend(['--extra-vars', ' '.join('{}="{}"'.format(k, v) for k, v in extra_vars.items())])

    if ansible_args:
        for key, value in ansible_args.items():
            if value is True:
                command.append('--{}'.format(key))
            elif value is False:
                command.append('--no-{}'.format(key))
            else:
                command.extend(['--{}'.format(key), str(value)])

    try:
        subprocess.run(command, check=True)
    except subprocess.CalledProcessError as e:
        raise RuntimeError("Ansible playbook failed with error: {}".format(e))

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import os

    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"The playbook path {playbook_path} does not exist or is not a file.")

    command = ['ansible-playbook', playbook_path]

    if verbose:
        command.extend(['-v'] * verbose)

    if extra_vars:
        extra_vars_str = ','.join(f'{key}={value}' for key, value in extra_vars.items())
        command.extend(['--extra-vars', extra_vars_str])

    if ansible_args:
        for key, value in ansible_args.items():
            if value is not None:
                command.extend(['--' + key, str(value)])
            else:
                command.append('--' + key)

    try:
        result = subprocess.run(command, check=True, text=True, capture_output=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Ansible playbook failed with return code {e.returncode}\n{e.stderr}") from e
    except Exception as e:
        raise RuntimeError(f"An error occurred while running the ansible playbook: {e}") from e

